create table if not exists public.student_home_slides (
  id bigint generated by default as identity primary key,
  draft jsonb not null default '{}'::jsonb,
  published jsonb,
  display_order integer not null default 100,
  is_active boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint student_home_slides_draft_object check (jsonb_typeof(draft) = 'object'),
  constraint student_home_slides_published_object check (published is null or jsonb_typeof(published) = 'object')
);
alter table public.student_home_slides enable row level security;
revoke all on public.student_home_slides from public, anon, authenticated;
grant select, insert, update, delete on public.student_home_slides to service_role;
grant usage, select on sequence public.student_home_slides_id_seq to service_role;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('student-home-banners', 'student-home-banners', false, 3145728, array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

alter table public.notices add column if not exists starts_at timestamptz;
alter table public.notices add column if not exists ends_at timestamptz;
alter table public.notices add constraint notices_valid_schedule check (ends_at is null or starts_at is null or ends_at > starts_at);

